Method.Source:
/// <summary>
/// AVA
/// </summary>
/// <param name = "_common">common</param>
/// <param name = "_tableToCreate">common</param>
/// <returns>boolean</returns>
public static boolean initFromCommon(Common _common, Common _tableToCreate)
{
    boolean         ret = next initFromCommon(_common,_tableToCreate);

    if ((_common.TableId == tableNum(smmBusRelTable) && _tableToCreate.TableId == tableNum(ContactPerson))
        || _common.TableId == tableNum(CustTable) && _tableToCreate.TableId == tableNum(ContactPerson))
    {
        FieldId             toParty = fieldName2id(_tableToCreate.TableId, identifierStr(Party));
        _tableToCreate.(toParty) = 0;
    }

    return ret;
}
